package ru.stepanov.selfcontrol.banking; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="acceptances") public class Acceptance{ @Id @Column(name="acceptance_id") private UUID acceptanceId; @Column(name="user_id",nullable=false) private UUID userId; private String externalConsentId; @Enumerated(EnumType.STRING) private AcceptanceStatus status; private Instant grantedAt; private Instant expiresAt; private Instant revokedAt; @Embedded private AcceptanceLimit acceptanceLimit; @OneToMany(mappedBy="acceptance") private List<LinkedAccount> linkedAccounts=new ArrayList<>(); @PrePersist void pre(){if(acceptanceId==null)acceptanceId=UUID.randomUUID(); if(status==null)status=AcceptanceStatus.Active; if(grantedAt==null)grantedAt=Instant.now();} public UUID getAcceptanceId(){return acceptanceId;} public void setAcceptanceId(UUID acceptanceId){this.acceptanceId=acceptanceId;} public UUID getUserId(){return userId;} public void setUserId(UUID userId){this.userId=userId;} public String getExternalConsentId(){return externalConsentId;} public void setExternalConsentId(String externalConsentId){this.externalConsentId=externalConsentId;} public AcceptanceStatus getStatus(){return status;} public void setStatus(AcceptanceStatus status){this.status=status;} public Instant getGrantedAt(){return grantedAt;} public void setGrantedAt(Instant grantedAt){this.grantedAt=grantedAt;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant expiresAt){this.expiresAt=expiresAt;} public Instant getRevokedAt(){return revokedAt;} public void setRevokedAt(Instant revokedAt){this.revokedAt=revokedAt;} public AcceptanceLimit getAcceptanceLimit(){return acceptanceLimit;} public void setAcceptanceLimit(AcceptanceLimit acceptanceLimit){this.acceptanceLimit=acceptanceLimit;} }
